{
  "name": "http-status-server",
  "version": "1.0.0",
  "description": "Node.js HTTP server with an HTTP status code lookup table",
  "type": "module",
  "main": "src/server.js",
  "scripts": {
    "start": "node src/server.js",
    "test": "node --test"
  },
  "engines": {
    "node": ">=18"
  },
  "license": "MIT"
}

import { STATUS_CODES } from "node:http";

export const statusCodes = { ...STATUS_CODES };

export function reasonPhrase(code) {
  const message = statusCodes[code];
  if (!message) {
    throw new RangeError(`Unknown HTTP status code: ${code}`);
  }
  return message;
}

export function isStatusCode(code) {
  return Object.prototype.hasOwnProperty.call(statusCodes, code);
}

import { createServer } from "node:http";
import { reasonPhrase } from "./status-codes.js";

const PORT = process.env.PORT ?? 3000;

const server = createServer((req, res) => {
  const url = new URL(req.url, `http://${req.headers.host}`);
  const code = Number(url.searchParams.get("code") ?? 200);

  let body;
  let status;

  try {
    body = `${code} ${reasonPhrase(code)}\n`;
    status = code;
  } catch {
    status = 400;
    body = `Unknown HTTP status code: ${code}\n`;
  }

  res.writeHead(status, { "content-type": "text/plain; charset=utf-8" });
  res.end(body);
});

server.listen(PORT, () => {
  console.log(`Server listening on http://localhost:${PORT}`);
});

import { test } from "node:test";
import assert from "node:assert/strict";
import { reasonPhrase, isStatusCode, statusCodes } from "../src/status-codes.js";

test("returns standard reason phrases", () => {
  assert.equal(reasonPhrase(200), "OK");
  assert.equal(reasonPhrase(404), "Not Found");
  assert.equal(reasonPhrase(500), "Internal Server Error");
  assert.equal(reasonPhrase(418), "I'm a Teapot");
});

test("throws on unknown status codes", () => {
  assert.throws(() => reasonPhrase(999), RangeError);
});

test("isStatusCode distinguishes known codes", () => {
  assert.equal(isStatusCode(204), true);
  assert.equal(isStatusCode(999), false);
});

test("exposes the full lookup table", () => {
  assert.ok(Object.keys(statusCodes).length > 50);
});
